        /// nil when none was asked or the last asked nil.
        func lastInput(cacheDir: URL, media: UInt32) -> MediaColor? {
            let key = "\(cacheDir.standardizedFileURL.path)\u{0}\(media)"
            condition.lock()

            condition.lock()
            defer { condition.unlock() }
